    <div class="zeye-status-wrapper" id="zeye-status-container">
        <div class="zeye-error">正在读取魔力印记...</div>
    </div>

    <script>
        /* ========== 手风琴交互逻辑 ========== */
        function toggleZeyeAccordion(element) {
            var accordion = element.parentElement;
            if (accordion.classList.contains('zeye-collapsed')) {
                accordion.classList.remove('zeye-collapsed');
            } else {
                accordion.classList.add('zeye-collapsed');
            }
        }

        /* ========== 获取消息内容 ========== */
        function getZeyeMessageData() {
            try {
                var chatMessages = getChatMessages(getCurrentMessageId());
                if (!chatMessages || chatMessages.length === 0) {
                    return null;
                }
                return chatMessages[0].message;
            } catch (e) {
                return null;
            }
        }

        /* ========== 解析数据 ========== */
        function parseZeyeData(messageText) {
            var result = {
                date: '未知星历',
                time: '时间停滞',
                thought: '...'
            };

            var tagMatch = messageText.match(/<zeyestatus>([\s\S]*?)<\/zeyestatus>/);
            if (!tagMatch || !tagMatch[1]) {
                return result;
            }
            var content = tagMatch[1];

            /* 解析 [字段|值] 格式 */
            var regex = /\[([^\|]+)\|([^\]]+)\]/g;
            var match;
            while ((match = regex.exec(content)) !== null) {
                var key = match[1].trim();
                var val = match[2].trim();
                if (key === '日期') result.date = val;
                if (key === '时间') result.time = val;
                if (key === '碎碎念') result.thought = val;
            }

            return result;
        }

        /* ========== 渲染界面 ========== */
        function renderZeyePage(data) {
            var html = `
                <!-- 装饰物 -->
                <div class="zeye-magic-circle"></div>
                <div class="zeye-particle zeye-p1"></div>
                <div class="zeye-particle zeye-p2"></div>
                <div class="zeye-particle zeye-p3"></div>

                <div class="zeye-content-box">
                    <!-- 头部信息 -->
                    <div class="zeye-header">
                        <div class="zeye-avatar-container">
                            <div class="zeye-avatar-frame"></div>
                            <!-- 使用酒馆内置角色头像类，自动拉取char头像 -->
                            <div class="char-avatar"></div>
                        </div>
                        <div class="zeye-info-area">
                            <div class="zeye-name">泽夜 Zeye</div>
                            <div class="zeye-time-row">
                                <div class="zeye-tag">✧ ${data.date}</div>
                                <div class="zeye-tag">⏱ ${data.time}</div>
                            </div>
                        </div>
                    </div>

                    <!-- 碎碎念气泡 (手风琴) -->
                    <!-- 默认不带 zeye-collapsed 类，即默认展开 -->
                    <div class="zeye-bubble-accordion">
                        <div class="zeye-accordion-header" onclick="toggleZeyeAccordion(this)">
                            <span>✦ 隐秘观测记录</span>
                            <span class="zeye-arrow">▼</span>
                        </div>
                        <div class="zeye-accordion-content">
                            "${data.thought}"
                        </div>
                    </div>
                </div>
            `;
            document.getElementById('zeye-status-container').innerHTML = html;
        }

        /* ========== 主函数 ========== */
        function initZeyeStatus() {
            try {
                var messageText = getZeyeMessageData();
                if (!messageText) {
                    document.getElementById('zeye-status-container').innerHTML =
                        '<div class="zeye-error">无法连接至高塔终端...</div>';
                    return;
                }
                var data = parseZeyeData(messageText);
                renderZeyePage(data);
            } catch (error) {
                document.getElementById('zeye-status-container').innerHTML =
                    '<div class="zeye-error">魔力紊乱：' + error.message + '</div>';
            }
        }

        /* 页面加载时执行 */
        $(function() { initZeyeStatus(); });
    </script>
</body>
